-- HAND-AUTHORED, NOT MACHINE-VALIDATED.
--
-- This migration was written by hand against prisma/schema.prisma, not
-- generated by `prisma migrate dev` — this sandbox has no network access
-- (cannot install the Prisma CLI) and no reachable Postgres database
-- (cannot run a shadow-database diff). It has been carefully reviewed
-- against Prisma's documented Postgres SQL conventions (type mapping,
-- default-value generation, constraint/index naming) but has NOT been
-- executed or verified against a real database or Prisma's own migration
-- engine.
--
-- SAFER ALTERNATIVE, RECOMMENDED: delete this migration folder and run
--   npx prisma migrate dev --name init
-- yourself against a real (even a fresh/empty) database. Prisma will then
-- generate and verify an authoritative migration from schema.prisma
-- directly, which is more trustworthy than this hand-transcription.
--
-- IF YOU HAVE ALREADY RUN `prisma db push` AGAINST A REAL DATABASE (so the
-- tables below already exist there): do NOT run this migration as-is — it
-- will fail with "relation already exists" (a safe, loud failure, not data
-- loss). Instead, baseline that database into migration tracking with:
--   npx prisma migrate resolve --applied 20260101000000_init
-- which records this migration as already applied without running its SQL.
--
-- This is a single baseline representing the schema as of the end of
-- Phase 3 (Phase 1 + 2 + 2.1 + 3 combined). No earlier intermediate state
-- was ever actually deployed, so there is no real history to preserve as
-- separate migrations — see the "Taxonomy resolution" note in
-- schema.prisma for why the ChangeCategory enum here already reflects the
-- Phase 3 correction rather than an intermediate, never-deployed version.

-- ---------------------------------------------------------------------------
-- Enums
-- ---------------------------------------------------------------------------

CREATE TYPE "SourceType" AS ENUM ('HOMEPAGE', 'PRICING', 'PRODUCT', 'FEATURE', 'CHANGELOG', 'DOCUMENTATION', 'BLOG', 'COMPARISON', 'REVIEW', 'CUSTOM');

CREATE TYPE "ChangeCategory" AS ENUM ('FEATURE', 'PRICING', 'PRODUCT', 'DOCUMENTATION', 'CHANGELOG', 'INTEGRATION', 'LEGAL_POLICY', 'CONTENT', 'MARKETING', 'UNKNOWN');

CREATE TYPE "Severity" AS ENUM ('INFO', 'LOW', 'MEDIUM', 'HIGH', 'CRITICAL');

CREATE TYPE "FeatureLifecycle" AS ENUM ('ACTIVE', 'REMOVED', 'UNCERTAIN');

CREATE TYPE "SentimentLabel" AS ENUM ('POSITIVE', 'NEUTRAL', 'NEGATIVE', 'MIXED');

CREATE TYPE "ReportFormat" AS ENUM ('MARKDOWN', 'HTML', 'JSON');

CREATE TYPE "AlertDeliveryStatus" AS ENUM ('PENDING', 'SUCCESS', 'FAILED');

-- ---------------------------------------------------------------------------
-- Core competitor graph
-- ---------------------------------------------------------------------------

CREATE TABLE "Product" (
    "id" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "homepageUrl" TEXT NOT NULL,
    "notes" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "Product_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "Product_createdAt_idx" ON "Product"("createdAt");

CREATE TABLE "Source" (
    "id" TEXT NOT NULL,
    "productId" TEXT NOT NULL,
    "type" "SourceType" NOT NULL,
    "url" TEXT NOT NULL,
    "label" TEXT,
    "enabled" BOOLEAN NOT NULL DEFAULT true,
    "lastScrapedAt" TIMESTAMP(3),
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "Source_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "Source_productId_idx" ON "Source"("productId");
CREATE INDEX "Source_type_idx" ON "Source"("type");

CREATE TABLE "Snapshot" (
    "id" TEXT NOT NULL,
    "sourceId" TEXT NOT NULL,
    "fetchedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "requestedUrl" TEXT NOT NULL DEFAULT '',
    "finalUrl" TEXT,
    "statusCode" INTEGER,
    "contentHash" TEXT,
    "contentType" TEXT,
    "title" TEXT,
    "metaDescription" TEXT,
    "canonicalUrl" TEXT,
    "normalizedText" TEXT,
    "headings" JSONB,
    "links" JSONB,
    "structuredData" JSONB,
    "renderRequired" BOOLEAN NOT NULL DEFAULT false,
    "error" TEXT,
    "durationMs" INTEGER,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "Snapshot_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "Snapshot_sourceId_fetchedAt_idx" ON "Snapshot"("sourceId", "fetchedAt");
CREATE INDEX "Snapshot_contentHash_idx" ON "Snapshot"("contentHash");

CREATE TABLE "Change" (
    "id" TEXT NOT NULL,
    "productId" TEXT NOT NULL,
    "sourceId" TEXT NOT NULL,
    "fromSnapshotId" TEXT,
    "toSnapshotId" TEXT NOT NULL,
    "category" "ChangeCategory" NOT NULL,
    "severity" "Severity" NOT NULL DEFAULT 'LOW',
    "confidence" DOUBLE PRECISION,
    "summary" TEXT NOT NULL,
    "detail" TEXT,
    "diff" JSONB,
    "evidenceText" TEXT,
    "detectedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "Change_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "Change_fromSnapshotId_toSnapshotId_key" ON "Change"("fromSnapshotId", "toSnapshotId");
CREATE INDEX "Change_productId_detectedAt_idx" ON "Change"("productId", "detectedAt");
CREATE INDEX "Change_sourceId_detectedAt_idx" ON "Change"("sourceId", "detectedAt");
CREATE INDEX "Change_category_idx" ON "Change"("category");

-- ---------------------------------------------------------------------------
-- Pricing intelligence
-- ---------------------------------------------------------------------------

CREATE TABLE "PricingPlan" (
    "id" TEXT NOT NULL,
    "productId" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "active" BOOLEAN NOT NULL DEFAULT true,
    "firstSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "lastSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "PricingPlan_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "PricingPlan_productId_idx" ON "PricingPlan"("productId");

CREATE TABLE "PricingPoint" (
    "id" TEXT NOT NULL,
    "productId" TEXT NOT NULL,
    "pricingPlanId" TEXT NOT NULL,
    "price" DOUBLE PRECISION,
    "currency" TEXT,
    "billingPeriod" TEXT,
    "unit" TEXT,
    "isCustomPricing" BOOLEAN NOT NULL DEFAULT false,
    "limits" JSONB,
    "features" JSONB,
    "sourceId" TEXT,
    "snapshotId" TEXT,
    "evidenceText" TEXT,
    "capturedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "PricingPoint_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "PricingPoint_productId_capturedAt_idx" ON "PricingPoint"("productId", "capturedAt");
CREATE INDEX "PricingPoint_pricingPlanId_capturedAt_idx" ON "PricingPoint"("pricingPlanId", "capturedAt");

-- ---------------------------------------------------------------------------
-- Feature intelligence
-- ---------------------------------------------------------------------------

CREATE TABLE "Feature" (
    "id" TEXT NOT NULL,
    "canonicalName" TEXT NOT NULL,
    "aliases" TEXT[],
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "Feature_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "Feature_canonicalName_key" ON "Feature"("canonicalName");

CREATE TABLE "FeatureObservation" (
    "id" TEXT NOT NULL,
    "featureId" TEXT NOT NULL,
    "productId" TEXT NOT NULL,
    "status" "FeatureLifecycle" NOT NULL DEFAULT 'ACTIVE',
    "confidence" DOUBLE PRECISION,
    "firstSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "lastSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "sourceId" TEXT,
    "snapshotId" TEXT,
    "evidenceText" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "FeatureObservation_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "FeatureObservation_productId_status_idx" ON "FeatureObservation"("productId", "status");
CREATE INDEX "FeatureObservation_featureId_idx" ON "FeatureObservation"("featureId");

-- ---------------------------------------------------------------------------
-- Review intelligence
-- ---------------------------------------------------------------------------

CREATE TABLE "ReviewSource" (
    "id" TEXT NOT NULL,
    "productId" TEXT NOT NULL,
    "platform" TEXT NOT NULL,
    "url" TEXT,
    "enabled" BOOLEAN NOT NULL DEFAULT true,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "ReviewSource_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "ReviewSource_productId_idx" ON "ReviewSource"("productId");

CREATE TABLE "Review" (
    "id" TEXT NOT NULL,
    "reviewSourceId" TEXT NOT NULL,
    "productId" TEXT NOT NULL,
    "externalId" TEXT,
    "author" TEXT,
    "rating" DOUBLE PRECISION,
    "title" TEXT,
    "body" TEXT NOT NULL,
    "sourceUrl" TEXT,
    "publishedAt" TIMESTAMP(3),
    "collectedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "sentimentScore" DOUBLE PRECISION,
    "sentimentLabel" "SentimentLabel",
    "sentimentConfidence" DOUBLE PRECISION,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "Review_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "Review_reviewSourceId_externalId_key" ON "Review"("reviewSourceId", "externalId");
CREATE INDEX "Review_productId_publishedAt_idx" ON "Review"("productId", "publishedAt");

CREATE TABLE "ReviewTopic" (
    "id" TEXT NOT NULL,
    "key" TEXT NOT NULL,
    "label" TEXT NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ReviewTopic_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "ReviewTopic_key_key" ON "ReviewTopic"("key");

CREATE TABLE "ReviewTopicObservation" (
    "id" TEXT NOT NULL,
    "reviewId" TEXT NOT NULL,
    "reviewTopicId" TEXT NOT NULL,
    "sentiment" DOUBLE PRECISION,
    "frequency" INTEGER NOT NULL DEFAULT 1,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ReviewTopicObservation_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "ReviewTopicObservation_reviewTopicId_idx" ON "ReviewTopicObservation"("reviewTopicId");
CREATE INDEX "ReviewTopicObservation_reviewId_idx" ON "ReviewTopicObservation"("reviewId");

-- ---------------------------------------------------------------------------
-- Cross-competitor trends
-- ---------------------------------------------------------------------------

CREATE TABLE "Trend" (
    "id" TEXT NOT NULL,
    "category" TEXT NOT NULL,
    "term" TEXT,
    "periodStart" TIMESTAMP(3) NOT NULL,
    "periodEnd" TIMESTAMP(3) NOT NULL,
    "frequency" INTEGER NOT NULL DEFAULT 0,
    "growth" DOUBLE PRECISION,
    "acceleration" DOUBLE PRECISION,
    "competitorCount" INTEGER NOT NULL DEFAULT 0,
    "confidence" DOUBLE PRECISION,
    "evidence" JSONB,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "Trend_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "Trend_category_periodStart_idx" ON "Trend"("category", "periodStart");

CREATE TABLE "TrendProduct" (
    "trendId" TEXT NOT NULL,
    "productId" TEXT NOT NULL,
    CONSTRAINT "TrendProduct_pkey" PRIMARY KEY ("trendId", "productId")
);

-- ---------------------------------------------------------------------------
-- Reports
-- ---------------------------------------------------------------------------

CREATE TABLE "Report" (
    "id" TEXT NOT NULL,
    "title" TEXT NOT NULL,
    "format" "ReportFormat" NOT NULL DEFAULT 'MARKDOWN',
    "periodStart" TIMESTAMP(3) NOT NULL,
    "periodEnd" TIMESTAMP(3) NOT NULL,
    "content" TEXT NOT NULL,
    "aiEnhanced" BOOLEAN NOT NULL DEFAULT false,
    "aiProvider" TEXT,
    "aiModel" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "Report_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "Report_createdAt_idx" ON "Report"("createdAt");

CREATE TABLE "ReportProduct" (
    "reportId" TEXT NOT NULL,
    "productId" TEXT NOT NULL,
    CONSTRAINT "ReportProduct_pkey" PRIMARY KEY ("reportId", "productId")
);

-- ---------------------------------------------------------------------------
-- Alerts
-- ---------------------------------------------------------------------------

CREATE TABLE "AlertWebhook" (
    "id" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "url" TEXT NOT NULL,
    "secret" TEXT,
    "eventTypes" TEXT[],
    "enabled" BOOLEAN NOT NULL DEFAULT true,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "AlertWebhook_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "AlertDelivery" (
    "id" TEXT NOT NULL,
    "alertWebhookId" TEXT NOT NULL,
    "eventType" TEXT NOT NULL,
    "entityType" TEXT NOT NULL,
    "entityId" TEXT NOT NULL,
    "payload" JSONB NOT NULL,
    "status" "AlertDeliveryStatus" NOT NULL DEFAULT 'PENDING',
    "attempts" INTEGER NOT NULL DEFAULT 0,
    "responseStatus" INTEGER,
    "error" TEXT,
    "lastAttemptAt" TIMESTAMP(3),
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "AlertDelivery_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "AlertDelivery_alertWebhookId_status_idx" ON "AlertDelivery"("alertWebhookId", "status");
CREATE INDEX "AlertDelivery_entityType_entityId_idx" ON "AlertDelivery"("entityType", "entityId");

-- ---------------------------------------------------------------------------
-- Public API auth
-- ---------------------------------------------------------------------------

CREATE TABLE "ApiKey" (
    "id" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "keyPrefix" TEXT NOT NULL,
    "hashedKey" TEXT NOT NULL,
    "scopes" TEXT[],
    "lastUsedAt" TIMESTAMP(3),
    "revokedAt" TIMESTAMP(3),
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ApiKey_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "ApiKey_hashedKey_key" ON "ApiKey"("hashedKey");
CREATE INDEX "ApiKey_keyPrefix_idx" ON "ApiKey"("keyPrefix");

-- ---------------------------------------------------------------------------
-- Foreign keys (added after every referenced table exists)
-- ---------------------------------------------------------------------------

ALTER TABLE "Source" ADD CONSTRAINT "Source_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "Snapshot" ADD CONSTRAINT "Snapshot_sourceId_fkey" FOREIGN KEY ("sourceId") REFERENCES "Source"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "Change" ADD CONSTRAINT "Change_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Change" ADD CONSTRAINT "Change_sourceId_fkey" FOREIGN KEY ("sourceId") REFERENCES "Source"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Change" ADD CONSTRAINT "Change_fromSnapshotId_fkey" FOREIGN KEY ("fromSnapshotId") REFERENCES "Snapshot"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "Change" ADD CONSTRAINT "Change_toSnapshotId_fkey" FOREIGN KEY ("toSnapshotId") REFERENCES "Snapshot"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "PricingPlan" ADD CONSTRAINT "PricingPlan_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "PricingPoint" ADD CONSTRAINT "PricingPoint_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "PricingPoint" ADD CONSTRAINT "PricingPoint_pricingPlanId_fkey" FOREIGN KEY ("pricingPlanId") REFERENCES "PricingPlan"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "FeatureObservation" ADD CONSTRAINT "FeatureObservation_featureId_fkey" FOREIGN KEY ("featureId") REFERENCES "Feature"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "FeatureObservation" ADD CONSTRAINT "FeatureObservation_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "ReviewSource" ADD CONSTRAINT "ReviewSource_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "Review" ADD CONSTRAINT "Review_reviewSourceId_fkey" FOREIGN KEY ("reviewSourceId") REFERENCES "ReviewSource"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Review" ADD CONSTRAINT "Review_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "ReviewTopicObservation" ADD CONSTRAINT "ReviewTopicObservation_reviewId_fkey" FOREIGN KEY ("reviewId") REFERENCES "Review"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ReviewTopicObservation" ADD CONSTRAINT "ReviewTopicObservation_reviewTopicId_fkey" FOREIGN KEY ("reviewTopicId") REFERENCES "ReviewTopic"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "TrendProduct" ADD CONSTRAINT "TrendProduct_trendId_fkey" FOREIGN KEY ("trendId") REFERENCES "Trend"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "TrendProduct" ADD CONSTRAINT "TrendProduct_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "ReportProduct" ADD CONSTRAINT "ReportProduct_reportId_fkey" FOREIGN KEY ("reportId") REFERENCES "Report"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ReportProduct" ADD CONSTRAINT "ReportProduct_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE "AlertDelivery" ADD CONSTRAINT "AlertDelivery_alertWebhookId_fkey" FOREIGN KEY ("alertWebhookId") REFERENCES "AlertWebhook"("id") ON DELETE CASCADE ON UPDATE CASCADE;
